create table if not exists public.gcc_customs_hs_tariffs (hs_code text primary key, description text not null, country_code text not null check (country_code in ('AE','SA','BH','KW','OM','QA')), duty_rate_bps integer not null check (duty_rate_bps between 0 and 10000), effective_from date not null, effective_to date, source_reference text not null, created_at timestamptz not null default now(), check (effective_to is null or effective_to > effective_from));

create table if not exists public.gcc_cross_border_manifests (manifest_id uuid primary key default gen_random_uuid(), business_id uuid not null, seller_business_id uuid not null, buyer_business_id uuid not null, origin_country text not null check (origin_country in ('AE','SA','BH','KW','OM','QA')), destination_country text not null check (destination_country in ('AE','SA','BH','KW','OM','QA')), manifest_number text not null, status text not null default 'draft' check (status in ('draft','submitted','customs_hold','customs_cleared','dispatched','delivered','cancelled')), currency_code text not null references public.gcc_supported_currencies(currency_code), total_declared_value numeric(18,4) not null default 0 check (total_declared_value >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (business_id, manifest_number), check (seller_business_id <> buyer_business_id), check (origin_country <> destination_country));

create table if not exists public.gcc_cross_border_manifest_lines (manifest_line_id uuid primary key default gen_random_uuid(), manifest_id uuid not null references public.gcc_cross_border_manifests(manifest_id) on delete restrict, source_dispatch_id uuid, ingredient_id uuid, hs_code text not null references public.gcc_customs_hs_tariffs(hs_code), quantity numeric(18,6) not null check (quantity > 0), unit_code text not null, declared_unit_value numeric(18,4) not null check (declared_unit_value >= 0), declared_value numeric(18,4) generated always as (round(quantity * declared_unit_value,4)) stored, created_at timestamptz not null default now(), unique (manifest_id, source_dispatch_id, ingredient_id, hs_code));

create table if not exists public.gcc_customs_events (customs_event_id uuid primary key default gen_random_uuid(), manifest_id uuid not null references public.gcc_cross_border_manifests(manifest_id) on delete restrict, event_type text not null check (event_type in ('manifest_created','customs_submitted','customs_hold','customs_cleared','customs_rejected','release_authorized')), event_payload jsonb not null default '{}'::jsonb, previous_hash text, event_hash text not null, created_at timestamptz not null default now(), created_by uuid, unique (manifest_id,event_hash));

create table if not exists public.gcc_cross_border_escrow (escrow_id uuid primary key default gen_random_uuid(), manifest_id uuid not null unique references public.gcc_cross_border_manifests(manifest_id) on delete restrict, business_id uuid not null, amount_minor bigint not null check (amount_minor >= 0), currency_code text not null references public.gcc_supported_currencies(currency_code), status text not null default 'pending' check (status in ('pending','funded','customs_cleared','released','refunded','disputed')), funded_at timestamptz, cleared_at timestamptz, released_at timestamptz, refunded_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

create table if not exists public.gcc_cross_border_pod (pod_id uuid primary key default gen_random_uuid(), manifest_id uuid not null unique references public.gcc_cross_border_manifests(manifest_id) on delete restrict, delivered_at timestamptz, received_by uuid, evidence_hash text, status text not null default 'pending' check (status in ('pending','submitted','verified','rejected')), created_at timestamptz not null default now());

alter table public.gcc_customs_hs_tariffs enable row level security;
alter table public.gcc_cross_border_manifests enable row level security;
alter table public.gcc_cross_border_manifest_lines enable row level security;
alter table public.gcc_customs_events enable row level security;
alter table public.gcc_cross_border_escrow enable row level security;
alter table public.gcc_cross_border_pod enable row level security;

create policy gcc_customs_tariffs_authenticated_select on public.gcc_customs_hs_tariffs for select to authenticated using (true);
create policy gcc_manifest_authenticated_select on public.gcc_cross_border_manifests for select to authenticated using (business_id = auth.uid() or seller_business_id = auth.uid() or buyer_business_id = auth.uid());
create policy gcc_manifest_lines_authenticated_select on public.gcc_cross_border_manifest_lines for select to authenticated using (exists (select 1 from public.gcc_cross_border_manifests m where m.manifest_id = manifest_id and (m.business_id = auth.uid() or m.seller_business_id = auth.uid() or m.buyer_business_id = auth.uid())));
create policy gcc_customs_events_authenticated_select on public.gcc_customs_events for select to authenticated using (exists (select 1 from public.gcc_cross_border_manifests m where m.manifest_id = manifest_id and (m.business_id = auth.uid() or m.seller_business_id = auth.uid() or m.buyer_business_id = auth.uid())));
create policy gcc_escrow_authenticated_select on public.gcc_cross_border_escrow for select to authenticated using (business_id = auth.uid() or exists (select 1 from public.gcc_cross_border_manifests m where m.manifest_id = manifest_id and (m.seller_business_id = auth.uid() or m.buyer_business_id = auth.uid())));
create policy gcc_pod_authenticated_select on public.gcc_cross_border_pod for select to authenticated using (exists (select 1 from public.gcc_cross_border_manifests m where m.manifest_id = manifest_id and (m.business_id = auth.uid() or m.seller_business_id = auth.uid() or m.buyer_business_id = auth.uid())));

revoke all on public.gcc_customs_hs_tariffs, public.gcc_cross_border_manifests, public.gcc_cross_border_manifest_lines, public.gcc_customs_events, public.gcc_cross_border_escrow, public.gcc_cross_border_pod from anon, authenticated;
grant select on public.gcc_customs_hs_tariffs, public.gcc_cross_border_manifests, public.gcc_cross_border_manifest_lines, public.gcc_customs_events, public.gcc_cross_border_escrow, public.gcc_cross_border_pod to authenticated;

create index if not exists gcc_manifest_seller_idx on public.gcc_cross_border_manifests(seller_business_id);
create index if not exists gcc_manifest_buyer_idx on public.gcc_cross_border_manifests(buyer_business_id);
create index if not exists gcc_manifest_lines_manifest_idx on public.gcc_cross_border_manifest_lines(manifest_id);
create index if not exists gcc_customs_events_manifest_idx on public.gcc_customs_events(manifest_id, created_at);
create index if not exists gcc_escrow_business_idx on public.gcc_cross_border_escrow(business_id);

create or replace function public.gcc_create_cross_border_manifest(p_business_id uuid,p_seller_business_id uuid,p_buyer_business_id uuid,p_origin_country text,p_destination_country text,p_manifest_number text,p_currency_code text) returns uuid language plpgsql security definer set search_path=pg_catalog,public,extensions,pg_temp as $f$ declare v_id uuid; begin if p_business_id is null or p_seller_business_id is null or p_buyer_business_id is null or p_seller_business_id=p_buyer_business_id or p_origin_country=p_destination_country or length(btrim(p_manifest_number))=0 or p_currency_code is null then raise exception 'invalid cross-border manifest'; end if; if p_origin_country not in ('AE','SA','BH','KW','OM','QA') or p_destination_country not in ('AE','SA','BH','KW','OM','QA') then raise exception 'unsupported GCC country'; end if; perform pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business_id::text||':'||p_manifest_number,0)); insert into public.gcc_cross_border_manifests(business_id,seller_business_id,buyer_business_id,origin_country,destination_country,manifest_number,currency_code) values(p_business_id,p_seller_business_id,p_buyer_business_id,p_origin_country,p_destination_country,p_manifest_number,p_currency_code) returning manifest_id into v_id; insert into public.gcc_cross_border_escrow(manifest_id,business_id,amount_minor,currency_code) values(v_id,p_business_id,0,p_currency_code); insert into public.gcc_cross_border_pod(manifest_id) values(v_id); return v_id; end $f$;

create or replace function public.gcc_append_customs_event(p_manifest_id uuid,p_event_type text,p_event_payload jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,public,extensions,pg_temp as $f$ declare v_prev text; v_hash text; v_id uuid; v_business uuid; begin select business_id into v_business from public.gcc_cross_border_manifests where manifest_id=p_manifest_id for update; if v_business is null then raise exception 'manifest not found'; end if; if p_event_type not in ('manifest_created','customs_submitted','customs_hold','customs_cleared','customs_rejected','release_authorized') then raise exception 'invalid customs event'; end if; perform pg_advisory_xact_lock(pg_catalog.hashtextextended(p_manifest_id::text,0)); select event_hash into v_prev from public.gcc_customs_events where manifest_id=p_manifest_id order by created_at desc,customs_event_id desc limit 1; v_hash=encode(extensions.digest(convert_to(p_manifest_id::text||':'||p_event_type||':'||p_event_payload::text||':'||coalesce(v_prev,''),'UTF8'),'sha256'),'hex'); insert into public.gcc_customs_events(manifest_id,event_type,event_payload,previous_hash,event_hash,created_by) values(p_manifest_id,p_event_type,p_event_payload,v_prev,v_hash,auth.uid()) returning customs_event_id into v_id; return v_id; end $f$;

create or replace function public.gcc_transition_cross_border_state(p_manifest_id uuid,p_target_state text) returns void language plpgsql security definer set search_path=pg_catalog,public,extensions,pg_temp as $f$ declare v_state text; begin select status into v_state from public.gcc_cross_border_manifests where manifest_id=p_manifest_id for update; if v_state is null then raise exception 'manifest not found'; end if; if not ((v_state='draft' and p_target_state='submitted') or (v_state='submitted' and p_target_state='customs_hold') or (v_state='submitted' and p_target_state='customs_cleared') or (v_state='customs_hold' and p_target_state='customs_cleared') or (v_state='customs_cleared' and p_target_state='dispatched') or (v_state='dispatched' and p_target_state='delivered') or (p_target_state='cancelled' and v_state not in ('delivered','cancelled'))) then raise exception 'invalid cross-border state transition'; end if; update public.gcc_cross_border_manifests set status=p_target_state,updated_at=now() where manifest_id=p_manifest_id; end $f$;

revoke execute on function public.gcc_create_cross_border_manifest(uuid,uuid,uuid,text,text,text,text) from public,anon,authenticated;
revoke execute on function public.gcc_append_customs_event(uuid,text,jsonb) from public,anon,authenticated;
revoke execute on function public.gcc_transition_cross_border_state(uuid,text) from public,anon,authenticated;
grant execute on function public.gcc_create_cross_border_manifest(uuid,uuid,uuid,text,text,text,text) to service_role;
grant execute on function public.gcc_append_customs_event(uuid,text,jsonb) to service_role;
grant execute on function public.gcc_transition_cross_border_state(uuid,text) to service_role;

drop trigger if exists gcc_customs_events_immutable_guard on public.gcc_customs_events;
create or replace function public.gcc_customs_events_immutable_guard() returns trigger language plpgsql set search_path=pg_catalog,public,extensions,pg_temp as $f$ begin raise exception 'customs events are append-only'; end $f$;
create trigger gcc_customs_events_immutable_guard before update or delete on public.gcc_customs_events for each row execute function public.gcc_customs_events_immutable_guard();
revoke update,delete,insert on public.gcc_customs_events from service_role;
revoke update,delete,insert on public.gcc_cross_border_pod from service_role;
revoke update,delete,insert on public.gcc_cross_border_manifest_lines from service_role;
revoke update,delete,insert on public.gcc_cross_border_manifests from service_role;
revoke update,delete,insert on public.gcc_cross_border_escrow from service_role;
revoke update,delete on public.gcc_customs_hs_tariffs from service_role;
grant select on public.gcc_customs_hs_tariffs,public.gcc_cross_border_manifests,public.gcc_cross_border_manifest_lines,public.gcc_customs_events,public.gcc_cross_border_escrow,public.gcc_cross_border_pod to service_role;
